CREATE TABLE "GEBRUIKER" (
  "gebruiker_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "naam" varchar NOT NULL,
  "leeftijd" int NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "wachtwoord_hash" varchar NOT NULL,
  "profielfoto" varchar,
  "woonplaats" varchar NOT NULL,
  "land" varchar NOT NULL,
  "aangemaakt_op" timestamp,
  "bijgewerkt_op" timestamp
);

CREATE TABLE "SPORT" (
  "sport_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "naam" varchar UNIQUE,
  "beschrijving" text
);

CREATE TABLE "ACTIVITEIT" (
  "activiteit_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "maker_id" int NOT NULL,
  "sport_id" int NOT NULL,
  "titel" varchar NOT NULL,
  "beschrijving" text,
  "starttijd" timestamp,
  "locatie_naam" varchar,
  "straatnaam" varchar,
  "huisnummer" varchar,
  "postcode" varchar,
  "woonplaats" varchar,
  "land" varchar,
  "breedtegraad" decimal,
  "lengtegraad" decimal,
  "externe_locatie_id" varchar,
  "maximaal_aantal_deelnemers" int,
  "status" varchar,
  "aangemaakt_op" timestamp,
  "bijgewerkt_op" timestamp
);

CREATE TABLE "ACTIVITEIT_DEELNEMER" (
  "activiteit_id" int,
  "gebruiker_id" int,
  "deelname_vanaf" timestamp,
  "rol" varchar,
  PRIMARY KEY ("activiteit_id", "gebruiker_id")
);

CREATE TABLE "GEBRUIKER_SPORTVOORKEUR" (
  "gebruiker_id" int,
  "sport_id" int,
  "voorkeursniveau" int NOT NULL DEFAULT 2,
  PRIMARY KEY ("gebruiker_id", "sport_id")
);

CREATE TABLE "GROEPSCHAT" (
  "chat_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "activiteit_id" int UNIQUE NOT NULL,
  "aangemaakt_op" timestamp,
  "verloopt_op" timestamp
);

CREATE TABLE "CHATLID" (
  "chatlid_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "chat_id" int NOT NULL,
  "gebruiker_id" int NOT NULL,
  "toegevoegd_op" timestamp,
  "verlaten_op" timestamp
);

CREATE TABLE "BERICHT" (
  "bericht_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "chat_id" int NOT NULL,
  "chatlid_id" int NOT NULL,
  "inhoud" text,
  "verzonden_op" timestamp
);

CREATE TABLE "RAPPORTAGE" (
  "rapportage_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "melder_id" int NOT NULL,
  "doel_gebruiker_id" int,
  "activiteit_id" int,
  "bericht_id" int,
  "reden" varchar NOT NULL,
  "toelichting" text,
  "status" varchar NOT NULL DEFAULT 'OPEN',
  "aangemaakt_op" timestamp NOT NULL,
  "afgehandeld_op" timestamp
);

CREATE TABLE "GEBRUIKER_BLOKKADE" (
  "blokkeerder_id" int NOT NULL,
  "geblokkeerde_id" int NOT NULL,
  "aangemaakt_op" timestamp NOT NULL,
  PRIMARY KEY ("blokkeerder_id", "geblokkeerde_id")
);

CREATE TABLE "NOTIFICATIE" (
  "notificatie_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gebruiker_id" int NOT NULL,
  "type" varchar NOT NULL,
  "titel" varchar NOT NULL,
  "inhoud" text,
  "activiteit_id" int,
  "bericht_id" int,
  "gelezen_op" timestamp,
  "aangemaakt_op" timestamp NOT NULL,
  "doel_url" text
);

CREATE TABLE "GEBRUIKER_NOTIFICATIEVOORKEUR" (
  "gebruiker_id" int NOT NULL,
  "categorie" varchar NOT NULL,
  "kanaal" varchar NOT NULL,
  "ingeschakeld" boolean NOT NULL DEFAULT true,
  PRIMARY KEY ("gebruiker_id", "categorie", "kanaal")
);

CREATE TABLE "BERICHT_BIJLAGE" (
  "bijlage_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bericht_id" int NOT NULL,
  "bestandspad" varchar NOT NULL,
  "bestandsnaam" varchar,
  "mime_type" varchar NOT NULL,
  "bestandsgrootte" int NOT NULL,
  "aangemaakt_op" timestamp NOT NULL
);

CREATE UNIQUE INDEX ON "CHATLID" ("chat_id", "gebruiker_id");

ALTER TABLE "ACTIVITEIT" ADD FOREIGN KEY ("maker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ACTIVITEIT" ADD FOREIGN KEY ("sport_id") REFERENCES "SPORT" ("sport_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ACTIVITEIT_DEELNEMER" ADD FOREIGN KEY ("activiteit_id") REFERENCES "ACTIVITEIT" ("activiteit_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "ACTIVITEIT_DEELNEMER" ADD FOREIGN KEY ("gebruiker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GEBRUIKER_SPORTVOORKEUR" ADD FOREIGN KEY ("gebruiker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GEBRUIKER_SPORTVOORKEUR" ADD FOREIGN KEY ("sport_id") REFERENCES "SPORT" ("sport_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GROEPSCHAT" ADD FOREIGN KEY ("activiteit_id") REFERENCES "ACTIVITEIT" ("activiteit_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "CHATLID" ADD FOREIGN KEY ("chat_id") REFERENCES "GROEPSCHAT" ("chat_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "CHATLID" ADD FOREIGN KEY ("gebruiker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "BERICHT" ADD FOREIGN KEY ("chat_id") REFERENCES "GROEPSCHAT" ("chat_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "BERICHT" ADD FOREIGN KEY ("chatlid_id") REFERENCES "CHATLID" ("chatlid_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RAPPORTAGE" ADD FOREIGN KEY ("melder_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RAPPORTAGE" ADD FOREIGN KEY ("doel_gebruiker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RAPPORTAGE" ADD FOREIGN KEY ("activiteit_id") REFERENCES "ACTIVITEIT" ("activiteit_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "RAPPORTAGE" ADD FOREIGN KEY ("bericht_id") REFERENCES "BERICHT" ("bericht_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GEBRUIKER_BLOKKADE" ADD FOREIGN KEY ("blokkeerder_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GEBRUIKER_BLOKKADE" ADD FOREIGN KEY ("geblokkeerde_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "NOTIFICATIE" ADD FOREIGN KEY ("gebruiker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "NOTIFICATIE" ADD FOREIGN KEY ("activiteit_id") REFERENCES "ACTIVITEIT" ("activiteit_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "NOTIFICATIE" ADD FOREIGN KEY ("bericht_id") REFERENCES "BERICHT" ("bericht_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "GEBRUIKER_NOTIFICATIEVOORKEUR" ADD FOREIGN KEY ("gebruiker_id") REFERENCES "GEBRUIKER" ("gebruiker_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "BERICHT_BIJLAGE" ADD FOREIGN KEY ("bericht_id") REFERENCES "BERICHT" ("bericht_id") DEFERRABLE INITIALLY IMMEDIATE;

-- Een rapportage moet precies één doel hebben.
ALTER TABLE "RAPPORTAGE"
  ADD CONSTRAINT "rapportage_exact_een_doel"
  CHECK (
    (("doel_gebruiker_id" IS NOT NULL)::int
    + ("activiteit_id" IS NOT NULL)::int
    + ("bericht_id" IS NOT NULL)::int) = 1
  );

-- Een gebruiker kan zichzelf niet blokkeren.
ALTER TABLE "GEBRUIKER_BLOKKADE"
  ADD CONSTRAINT "geen_zelfblokkade"
  CHECK ("blokkeerder_id" <> "geblokkeerde_id");

-- Voorkeursniveau: 1 = verborgen, 2 = normaal, 3 = favoriet.
ALTER TABLE "GEBRUIKER_SPORTVOORKEUR"
  ADD CONSTRAINT "voorkeursniveau_geldig"
  CHECK ("voorkeursniveau" IN (1, 2, 3));

-- Capaciteit: minimaal 2 en maximaal 50 deelnemers.
ALTER TABLE "ACTIVITEIT"
  ADD CONSTRAINT "activiteit_capaciteit_geldig"
  CHECK (
    "maximaal_aantal_deelnemers" IS NULL
    OR "maximaal_aantal_deelnemers" BETWEEN 2 AND 50
  );

-- Bestandsgrootte mag niet negatief zijn.
ALTER TABLE "BERICHT_BIJLAGE"
  ADD CONSTRAINT "bijlage_grootte_niet_negatief"
  CHECK ("bestandsgrootte" >= 0);
